def minimum_matching_card_pickup(cards):
    latest={};answer=float('inf')
    for index,value in enumerate(cards):
        if value in latest:answer=min(answer,index-latest[value]+1)
        latest[value]=index
    return -1 if answer==float('inf') else answer

